package java_basics;

public class Assignment_operator {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int sum=0;
		int a=20;
		
		System.out.println(sum +=a);//sum=sum+a
		System.out.println(sum -=a);//sum=sum-a
		System.out.println(sum *=a);//sum=sum*a
		System.out.println(sum /=a);//sum=sum/a
		System.out.println(sum %=a);//sum=sum%a

	}

}
